{"policy":"permit (
    principal is User,
    action == Action::"approveDeployment",
    resource is Deployment
)
when {
    (principal.isApprover || principal.isReleaseManager) &&
    (resource.changeRisk <= context.extraScrutinyThreshold || resource.submittedForReview)
};

forbid (
    principal is User,
    action == Action::"approveDeployment",
    resource is Deployment
)
when {
    (principal.isApprover || principal.isReleaseManager) &&
    resource.committer == principal
};"}
